import{_ as t,c as a,o,ae as n}from"./chunks/framework.Cd-3tpCq.js";const h=JSON.parse('{"title":"Mass Delete Cart Rule Coupons","description":"","frontmatter":{"outline":false,"examples":[{"id":"mass-delete","title":"Mass Delete Cart Rule Coupons","description":"Delete several coupons of one cart rule in a single call. Ids not on the rule are skipped.","query":"mutation CreateAdminMarketingCartRuleCouponMassDelete(\\n  $input: createAdminMarketingCartRuleCouponMassDeleteInput!\\n) {\\n  createAdminMarketingCartRuleCouponMassDelete(input: $input) {\\n    adminMarketingCartRuleCouponMassDelete {\\n      deleted\\n      skipped\\n      message\\n    }\\n  }\\n}\\n","variables":"{\\n  \\"input\\": {\\n    \\"cartRuleId\\": 47,\\n    \\"indices\\": [22, 23]\\n  }\\n}\\n","response":"{\\n  \\"data\\": {\\n    \\"createAdminMarketingCartRuleCouponMassDelete\\": {\\n      \\"adminMarketingCartRuleCouponMassDelete\\": {\\n        \\"deleted\\": [22, 23],\\n        \\"skipped\\": [],\\n        \\"message\\": \\"Cart rule coupons deleted.\\"\\n      }\\n    }\\n  }\\n}\\n"}]},"headers":[],"relativePath":"api/graphql-api/admin/marketing/promotions/cart-rule-coupons-mass-delete.md","filePath":"api/graphql-api/admin/marketing/promotions/cart-rule-coupons-mass-delete.md"}'),r={name:"api/graphql-api/admin/marketing/promotions/cart-rule-coupons-mass-delete.md"};function s(i,e,d,l,u,p){return o(),a("div",null,e[0]||(e[0]=[n('<h1 id="mass-delete-cart-rule-coupons" tabindex="-1">Mass Delete Cart Rule Coupons <a class="header-anchor" href="#mass-delete-cart-rule-coupons" aria-label="Permalink to &quot;Mass Delete Cart Rule Coupons&quot;">​</a></h1><p>Deletes several coupons of one cart rule in a single call — the <strong>Mass Delete</strong> action on the admin <strong>Marketing → Promotions → Cart Rules → Coupons</strong> datagrid.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>New here? Read the <a href="/api/graphql-api/admin/marketing/promotions/cart-rule-coupons/">Cart Rule Coupons overview</a> for what a coupon does and how its fields behave.</p></div><h2 id="operation" tabindex="-1">Operation <a class="header-anchor" href="#operation" aria-label="Permalink to &quot;Operation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Operation</th><th>Type</th><th>Purpose</th></tr></thead><tbody><tr><td><code>createAdminMarketingCartRuleCouponMassDelete</code></td><td>Mutation</td><td>Delete multiple coupons of one cart rule</td></tr></tbody></table><h2 id="details" tabindex="-1">Details <a class="header-anchor" href="#details" aria-label="Permalink to &quot;Details&quot;">​</a></h2><ul><li>Requires an admin Bearer token and the <code>marketing.promotions.cart_rules.delete</code> permission.</li><li>Pass the parent <code>cartRuleId</code> plus the numeric coupon ids in <code>indices</code>. Ids that do <strong>not</strong> belong to that cart rule are <strong>silently skipped</strong> (returned in <code>skipped</code>); the ids actually removed are returned in <code>deleted</code>.</li><li>An empty or missing <code>indices</code> list returns a <code>422</code> error.</li></ul><h2 id="input-fields" tabindex="-1">Input fields <a class="header-anchor" href="#input-fields" aria-label="Permalink to &quot;Input fields&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Required</th><th>Notes</th></tr></thead><tbody><tr><td><code>cartRuleId</code></td><td>Int</td><td>Yes</td><td>Parent cart-rule id</td></tr><tr><td><code>indices</code></td><td>Array</td><td>Yes</td><td>Non-empty list of numeric coupon ids to delete</td></tr></tbody></table>',9)]))}const m=t(r,[["render",s]]);export{h as __pageData,m as default};
